"use strict";

let store=loadStore(),ws=activeWorkspace(store);
const history=[];
const ui={search:'',selected:new Set(),detailId:null,detailSource:null,detailStack:[],popover:null,dialogKind:null,newLayout:'table',newSource:null,mobile:false,calendarMonth:'2026-10',timelineStart:'2026-10-05',mapSelected:null,toastTimer:null};
const $=selector=>document.querySelector(selector);
const currentView=()=>ws.views.find(v=>v.id===ws.activeView)||ws.views[0];
const currentRecords=()=>recordsFor(ws,currentView(),ui.search);
const dashboard=()=>currentView().layout==='dashboard';
const titleFor=()=>sourceFor(ws,currentView().sourceId)?.name||'업무 요약';
const options=(items,selected)=>items.map(o=>`<option value="${esc(o.id)}" ${o.id===selected?'selected':''}>${esc(o.label)}</option>`).join('');
const fieldOptions=(view,selected,test=()=>true)=>options(getFields(ws,view).filter(test).map(f=>({id:f.id,label:f.label})),selected);
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(store));}catch{toast('브라우저 저장 공간을 확인해 주세요.');}}
function mutate(fn,message,refresh=true){history.push(JSON.stringify(store));if(history.length>50)history.shift();fn();save();if(refresh)render();if(message)toast(message,true);}
function toast(message,undo=false){clearTimeout(ui.toastTimer);$('#toast').innerHTML=`${esc(message)}${undo?'<button data-action="undo">되돌리기</button>':''}`;$('#toast').classList.add('visible');ui.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3400);}
function undo(){if(!history.length)return;store=JSON.parse(history.pop());ws=activeWorkspace(store);resetUi();save();render();toast('이전 상태로 되돌렸어요.');}
function closePopover(){ui.popover=null;$('#popover-root').innerHTML='';}
function closeDetail(){ui.detailId=null;ui.detailStack=[];$('#detail-root').innerHTML='';}
function closeDialog(){if($('#dialog').open)$('#dialog').close();ui.dialogKind=null;}
function resetUi(){ui.search='';ui.selected.clear();ui.mobile=false;ui.mapSelected=null;closePopover();closeDialog();closeDetail();}
function chooseView(id){if(!ws.views.some(v=>v.id===id))return;resetUi();ws.activeView=id;save();render();}
function chooseWorkspace(id){if(!store.workspaces.some(w=>w.id===id))return;resetUi();store.activeWorkspaceId=id;ws=activeWorkspace(store);save();render();}
function canUse(layout,sourceId){const fields=ws.fields.filter(f=>f.scopes.includes(sourceId));if(layout==='dashboard')return true;if(['calendar','timeline','gantt'].includes(layout))return fields.some(f=>f.type==='date');if(layout==='map')return fields.some(f=>f.id==='lat');if(layout==='board')return fields.some(f=>f.type==='status'||f.id==='category');return true;}
function normalizeView(view){const fields=getFields(ws,view);if(!fields.some(f=>f.id===view.groupBy))view.groupBy=fields.find(f=>f.id==='category')?.id||fields[0]?.id||'name';if(!fields.some(f=>f.id===view.chartGroup))view.chartGroup=view.groupBy;if(!fields.some(f=>f.id===view.pivotRow))view.pivotRow=view.chartGroup;if(!fields.some(f=>f.id===view.pivotColumn))view.pivotColumn=view.chartGroup;if(!fields.some(f=>f.id===view.measure)){view.aggregate='count';view.measure=fields.find(f=>['number','currency'].includes(f.type))?.id||'amount';}}

function renderSidebar(){
 const view=currentView(),sourceId=view.sourceId;
 const navSource=s=>`<button class="nav-item ${s.id===sourceId?'active':''}" data-action="source" data-id="${s.id}"><span class="nav-icon">${icon(s.icon)}</span>${esc(s.name)}<span class="nav-count">${s.id==='companies'?ws.entities.length:s.type==='LIST'?Object.keys(ws.entries[s.id]).length:ws.records.length}</span></button>`;
 $('#sidebar').innerHTML=`<button class="workspace-switcher" data-action="workspaces" aria-label="워크스페이스 전환"><span class="workspace-symbol" style="background:${ws.tint};color:${ws.accent}">${ws.initial}</span><span><strong>${esc(ws.name)}</strong><small>${esc(ws.team)}</small></span>${icon('chevron',12)}</button><button class="quick-search" data-action="quick-search">${icon('search',14)}빠르게 찾기<span class="kbd">⌘ K</span></button><button class="nav-item ${dashboard()?'active':''}" data-action="home"><span class="nav-icon">${icon('dashboard')}</span>업무 요약</button><div class="nav-section">관리하는 정보</div>${ws.sources.filter(s=>s.type==='OBJECT').map(navSource).join('')}<div class="nav-section">업무 목록<span>2</span></div>${ws.sources.filter(s=>s.type==='LIST').map(navSource).join('')}<div class="nav-section">즐겨찾는 보기</div>${['board','calendar','chart','map'].map(type=>ws.views.find(v=>v.layout===type)).filter(Boolean).map(v=>`<button class="nav-item nav-inset" data-action="choose-view" data-id="${v.id}"><span class="nav-icon">${icon(layoutFor(v.layout).icon,14)}</span>${esc(v.name)}</button>`).join('')}<div class="nav-spacer"></div><button class="view-explorer" data-action="catalog">${icon('gallery',15)}<span>11가지 보기 둘러보기<small>같은 기록을 다양한 방식으로</small></span>${icon('right',13)}</button><button class="nav-item" data-action="help"><span class="nav-icon">${icon('right')}</span>목업 사용 안내</button><div class="preview-note"><span class="dot"></span>샘플 데이터 · 이 브라우저에 저장</div><div class="profile">${avatar(ws,ws.owners[0].id,true)}<div class="profile-info">${esc(ws.owners[0].label)}<small>OneHand CRM</small></div><button class="icon-btn" data-action="workspaces" aria-label="업무 공간 선택">${icon('dots')}</button></div>`;
}
function renderHeader(){
 const view=currentView();$('#page-header').innerHTML=`<button class="icon-btn mobile-toggle" data-action="mobile" aria-label="메뉴 열기">${icon('menu')}</button><span style="color:${ws.accent}">${icon(dashboard()?'dashboard':sourceFor(ws,view.sourceId)?.icon||'layers',17)}</span><span class="page-heading">${esc(titleFor())}</span>${sourceFor(ws,view.sourceId)?.type==='LIST'?`<span class="source-badge">${icon(ws.icon,11)}${esc(ws.labels.mainObject)}</span>`:''}<div class="header-right"><span class="saved-indicator">${icon('check',12)}저장됨</span><button class="workspace-context" data-action="workspaces"><span class="context-dot" style="background:${ws.accent}"></span>${esc(ws.team)}${icon('chevron',10)}</button>${avatar(ws,ws.owners[0].id)}</div>`;
}
function viewControls(view){
 if(view.layout==='chart')return `<select class="toolbar-select" aria-label="차트 형태" data-action="view-option" data-option="chartStyle">${options(chartStyles,view.chartStyle)}</select><select class="toolbar-select" aria-label="차트 그룹 기준" data-action="view-option" data-option="chartGroup">${fieldOptions(view,view.chartGroup,f=>!['currency','number','date','relation'].includes(f.type))}</select><select class="toolbar-select" aria-label="차트 집계 방법" data-action="view-option" data-option="aggregate"><option value="sum" ${view.aggregate==='sum'?'selected':''}>합계</option><option value="count" ${view.aggregate==='count'?'selected':''}>건수</option></select>${view.aggregate==='sum'?`<select class="toolbar-select" aria-label="차트 집계할 정보" data-action="view-option" data-option="measure">${fieldOptions(view,view.measure,f=>['currency','number'].includes(f.type))}</select>`:''}`;
 if(view.layout==='pivot')return `<span class="toolbar-caption">행</span><select class="toolbar-select" aria-label="피벗 행" data-action="view-option" data-option="pivotRow">${fieldOptions(view,view.pivotRow,f=>['text','status','person'].includes(f.type))}</select><span class="toolbar-caption">열</span><select class="toolbar-select" aria-label="피벗 열" data-action="view-option" data-option="pivotColumn">${fieldOptions(view,view.pivotColumn,f=>['text','status','person'].includes(f.type))}</select><select class="toolbar-select" aria-label="피벗 집계 방법" data-action="view-option" data-option="aggregate"><option value="sum" ${view.aggregate==='sum'?'selected':''}>합계</option><option value="count" ${view.aggregate==='count'?'selected':''}>건수</option></select>${view.aggregate==='sum'?`<select class="toolbar-select" aria-label="피벗 집계할 정보" data-action="view-option" data-option="measure">${fieldOptions(view,view.measure,f=>['currency','number'].includes(f.type))}</select>`:''}`;
 if(view.layout==='calendar')return `<select class="toolbar-select" aria-label="캘린더 날짜 기준" data-action="view-option" data-option="dateField">${fieldOptions(view,view.dateField,f=>f.type==='date')}</select>`;
 if(['timeline','gantt'].includes(view.layout))return `<select class="toolbar-select" aria-label="일정 시작일 기준" data-action="view-option" data-option="startField">${fieldOptions(view,view.startField,f=>f.type==='date')}</select><span class="toolbar-caption">→</span><select class="toolbar-select" aria-label="일정 종료일 기준" data-action="view-option" data-option="endField">${fieldOptions(view,view.endField,f=>f.type==='date')}</select>`;
 return '';
}
function renderBars(){
 const view=currentView();
 $('#view-bar').innerHTML=`<div class="view-tabs">${ws.views.filter(v=>v.sourceId===view.sourceId).map(v=>`<button class="view-tab ${v.id===view.id?'active':''}" data-action="choose-view" data-id="${v.id}" ${v.id===view.id?'aria-current="page"':''}>${icon(layoutFor(v.layout)?.icon||'table',13)}${esc(v.name)}</button>`).join('')}</div><button class="button quiet add-view-button" data-action="new-view" aria-label="보기 추가">${icon('plus',14)}<span class="add-view-label">보기</span></button><div class="bar-actions"><button class="button" data-action="catalog" aria-label="11가지 보기 선택">${icon(layoutFor(view.layout)?.icon,14)}<span class="settings-label">${layoutFor(view.layout)?.label}</span>${icon('chevron',11)}</button><button class="button" data-action="settings" aria-label="보기 설정">${icon('settings',14)}<span class="settings-label">설정</span></button>${dashboard()?'':`<button class="button primary" data-action="new-record">${icon('plus',14)}<span class="new-record-label">${esc(view.sourceId==='companies'?ws.labels.entity:ws.labels.record)} 추가</span></button>`}</div>`;
 $('#toolbar').style.display=dashboard()?'none':'flex';if(dashboard())return;
 const count=ruleCount(view.filter);$('#toolbar').innerHTML=`<button class="button ${count?'active':''}" data-action="filter">${icon('filter',13)}필터${count?`<span class="control-count">${count}</span>`:''}</button><button class="button ${view.sorts.length?'active':''}" data-action="sort">${icon('sort',13)}정렬${view.sorts.length?`<span class="control-count">${view.sorts.length}</span>`:''}</button>${['board','list'].includes(view.layout)?`<button class="button" data-action="group">${icon('group',13)}${esc(getField(ws,view.groupBy,view.sourceId)?.label||'그룹')}별</button>`:''}${viewControls(view)}<label class="search-box">${icon('search',13)}<input id="record-search" aria-label="현재 목록 검색" placeholder="검색" value="${esc(ui.search)}"></label>`;
 $('#record-search').addEventListener('input',e=>{ui.search=e.target.value;renderWorkspace();renderStatus();});
}
function renderWorkspace(){const view=currentView();$('#workspace').className=`workspace workspace-${view.layout}`;$('#workspace').innerHTML=renderView(ws,view,ui);if(ui.selected.size&&!dashboard())$('#workspace').insertAdjacentHTML('beforeend',`<div class="bulk-bar"><span>${ui.selected.size}개 선택</span>${sourceFor(ws,view.sourceId)?.type==='LIST'?'<button class="button small" data-action="bulk-stage">단계 변경</button>':''}<button class="icon-btn" data-action="deselect" aria-label="선택 해제">${icon('close',13)}</button></div>`);}
function renderStatus(){const view=currentView();$('#status-bar').innerHTML=`<span>${dashboard()?(view.widgets||[]).filter(w=>!w.hidden).length+'개 보기':currentRecords().length+'개 기록'}</span><span class="status-hint">${dashboard()?'기존 보기를 추가해 업무 요약을 구성하세요.':view.layout==='board'?'카드를 다른 열로 끌면 이 목록의 단계가 바뀝니다.':view.layout==='table'?'셀을 눌러 바로 수정할 수 있어요.':view.layout==='calendar'?'기록을 다른 날짜로 끌어 일정을 변경하세요.':'같은 기록의 변경은 다른 보기에도 반영됩니다.'}</span><span class="right"></span><button data-action="undo" ${history.length?'':'disabled'}>${icon('undo',11)} 되돌리기</button><button data-action="reset">예시 초기화</button>`;}
function render(){document.documentElement.style.setProperty('--blue',ws.accent);document.documentElement.style.setProperty('--accent-tint',ws.tint);document.title=`${ws.name} · OneHand CRM`;renderSidebar();renderHeader();renderBars();renderWorkspace();renderStatus();$('#app').classList.toggle('sidebar-open',ui.mobile);if(!$('.mobile-overlay'))$('#app').insertAdjacentHTML('beforeend','<button class="mobile-overlay" data-action="mobile" aria-label="메뉴 닫기"></button>');if(ui.detailId)renderDetail();}

function showPopover(kind,anchor,extra={}){closePopover();ui.popover={kind,rect:anchor.getBoundingClientRect(),...extra};renderPopover();}
function renderFilterGroup(view,group,nested=false){
 return `<div class="filter-group ${nested?'nested':''}"><div class="filter-group-head">아래 조건 중<select aria-label="조건 결합 방식" data-action="filter-operator" data-id="${group.id}"><option value="AND" ${group.operator==='AND'?'selected':''}>모두 만족</option><option value="OR" ${group.operator==='OR'?'selected':''}>하나라도 만족</option></select>하는 기록${nested?`<button class="icon-btn" data-action="remove-filter" data-id="${group.id}" aria-label="그룹 제거">${icon('close',12)}</button>`:''}</div>${group.rules.map(r=>{
  if(r.rules)return renderFilterGroup(view,r,true);const field=getField(ws,r.fieldId,view.sourceId),ops=['currency','number','date'].includes(field?.type)?[{id:'gte',label:'이상'},{id:'lte',label:'이하'},{id:'eq',label:'같음'},{id:'empty',label:'비어 있음'}]:[{id:'eq',label:'같음'},{id:'neq',label:'다름'},{id:'contains',label:'포함'},{id:'empty',label:'비어 있음'}];
  return `<div class="filter-rule"><select aria-label="필터 정보" class="filter-field" data-action="filter-field" data-id="${r.id}">${fieldOptions(view,r.fieldId)}</select><select aria-label="비교 방법" class="filter-op" data-action="filter-op" data-id="${r.id}">${options(ops,r.op)}</select>${r.op==='empty'?'':field?.options?`<select class="filter-value" aria-label="비교 값" data-action="filter-value" data-id="${r.id}">${options(field.options,r.value)}</select>`:`<input class="filter-value" aria-label="비교 값" data-action="filter-value" data-id="${r.id}" type="${['number','currency'].includes(field?.type)?'number':field?.type==='date'?'date':'text'}" value="${esc(r.value)}" placeholder="비교 값">`}${field?.type==='multiselect'?`<select class="filter-op" aria-label="여러 값 비교" data-action="filter-match" data-id="${r.id}"><option value="ANY" ${r.matchMode!=='ALL'?'selected':''}>하나 이상</option><option value="ALL" ${r.matchMode==='ALL'?'selected':''}>모든 값</option></select>`:''}<button class="icon-btn" data-action="remove-filter" data-id="${r.id}" aria-label="조건 제거">${icon('close',12)}</button></div>`;
 }).join('')}<div class="filter-actions"><button class="button quiet small" data-action="add-filter" data-parent="${group.id}">${icon('plus',11)}조건 추가</button><button class="button quiet small" data-action="add-filter-group" data-parent="${group.id}">${icon('plus',11)}조건 그룹</button></div></div>`;
}
function renderPopover(){
 if(!ui.popover)return;const p=ui.popover,view=ws.views.find(v=>v.id===p.viewId)||currentView();let content='',wide=false;
 const head=title=>`<div class="popover-head">${title}<button class="icon-btn" data-action="close-popover" aria-label="메뉴 닫기">${icon('close',13)}</button></div>`;
 if(p.kind==='workspaces')content=head('워크스페이스 전환')+store.workspaces.map(w=>`<button class="workspace-option ${w.id===ws.id?'selected':''}" data-action="workspace" data-id="${w.id}"><span class="workspace-symbol" style="background:${w.tint};color:${w.accent}">${w.initial}</span><span><strong>${esc(w.name)}</strong><small>${esc(w.description)}</small></span>${w.id===ws.id?icon('check',14):''}</button>`).join('')+'<div class="popover-sub">각 공간의 데이터와 보기 설정은 따로 저장돼요.</div>';
 if(p.kind==='settings')content=head('보기 설정')+`<label class="config-label">보기 이름</label><input class="config-control" data-action="view-name" value="${esc(view.name)}"><button class="menu-item" data-action="change-type">${icon(layoutFor(view.layout)?.icon,15)}보기 방식 변경<span class="right">${layoutFor(view.layout)?.label}</span></button>${dashboard()?'':`<button class="menu-item" data-action="properties">${icon('eye',15)}표시할 정보</button><button class="menu-item" data-action="filter">${icon('filter',15)}필터</button><button class="menu-item" data-action="sort">${icon('sort',15)}정렬</button>${['board','list'].includes(view.layout)?'<button class="menu-item" data-action="group">'+icon('group',15)+'그룹 설정</button>':''}`}<div class="menu-divider"></div><button class="menu-item" data-action="duplicate-view">${icon('copy',15)}현재 보기 복제</button><button class="menu-item" data-action="delete-view">${icon('trash',15)}보기 삭제</button>`;
 if(p.kind==='properties')content=head('표시할 정보')+'<div class="popover-sub">현재 보기에서 보일 정보와 순서를 바꿉니다.</div>'+getFields(ws,view).map(f=>{const prop=view.props.find(p=>p.fieldId===f.id);return `<div class="field-row">${icon(f.icon,14)}<span class="field-label">${esc(f.label)}<small class="field-source">${esc(f.source)}</small></span>${prop?`<button class="icon-btn" data-action="move-prop" data-field="${f.id}" data-step="-1" aria-label="${esc(f.label)} 위로">${icon('up',12)}</button><button class="icon-btn" data-action="move-prop" data-field="${f.id}" data-step="1" aria-label="${esc(f.label)} 아래로">${icon('down',12)}</button>`:''}<input type="checkbox" data-action="toggle-property" data-field="${f.id}" aria-label="${esc(f.label)} 표시" ${prop&&!prop.hidden?'checked':''}></div>`;}).join('')+`<div class="menu-divider"></div><label class="config-label">기록 제목</label><select class="config-control" data-action="card-title">${fieldOptions(view,view.props.find(p=>p.role==='TITLE')?.fieldId)}</select>${['board','gallery'].includes(view.layout)?`<div class="field-row"><span class="field-label">정보 이름도 함께 표시</span><input type="checkbox" data-action="show-labels" aria-label="정보 이름 표시" ${view.showLabels?'checked':''}></div>`:''}<button class="menu-item" data-action="new-field">${icon('plus',14)}새로운 정보 추가</button>`;
 if(p.kind==='field'){const field=getField(ws,p.fieldId,view.sourceId),prop=view.props.find(item=>item.fieldId===p.fieldId);content=head(esc(field.label))+`<label class="config-label">이 보기에서 사용할 이름</label><input class="config-control" data-action="property-label" data-field="${field.id}" value="${esc(prop?.label||field.label)}"><label class="config-label">열 너비</label><input class="config-control" type="number" data-action="property-width" data-field="${field.id}" value="${prop?.width||180}"><div class="menu-divider"></div><button class="menu-item" data-action="hide-property" data-field="${field.id}">${icon('eye',15)}이 보기에서 숨기기</button><button class="menu-item" data-action="sort-field" data-field="${field.id}" data-direction="ASC">${icon('sort',15)}오름차순 정렬</button><button class="menu-item" data-action="sort-field" data-field="${field.id}" data-direction="DESC">${icon('sort',15)}내림차순 정렬</button>`;}
 if(p.kind==='sort')content=head('정렬')+'<div class="popover-sub">위쪽 기준부터 적용합니다.</div>'+view.sorts.map((s,i)=>`<div class="sort-row"><button class="icon-btn" data-action="sort-up" data-id="${s.id}" aria-label="정렬 우선순위 올리기" ${i===0?'disabled':''}>${icon('up',12)}</button><select aria-label="정렬할 정보" data-action="sort-field-change" data-id="${s.id}">${fieldOptions(view,s.fieldId)}</select><select aria-label="정렬 방향" data-action="sort-direction" data-id="${s.id}"><option value="ASC" ${s.direction==='ASC'?'selected':''}>오름차순</option><option value="DESC" ${s.direction==='DESC'?'selected':''}>내림차순</option></select><button class="icon-btn" data-action="remove-sort" data-id="${s.id}" aria-label="정렬 제거">${icon('close',12)}</button></div>`).join('')+'<div class="popover-footer"><button class="button quiet" data-action="add-sort">'+icon('plus',13)+'정렬 추가</button><button class="button quiet" data-action="clear-sort">초기화</button></div>';
 if(p.kind==='filter'){wide=true;content=head('필터')+'<div class="popover-sub">조건을 바꾸면 화면에 바로 반영됩니다.</div>'+renderFilterGroup(view,view.filter)+`<div class="popover-footer"><span></span><button class="button quiet" data-action="clear-filters" data-view="${view.id}">전체 초기화</button></div>`;}
 if(p.kind==='group')content=head('그룹 설정')+`<label class="config-label">그룹 기준</label><select class="config-control" data-action="group-by">${fieldOptions(view,view.groupBy,f=>['status','person','text'].includes(f.type)&&f.id!=='name')}</select><div class="menu-section">열 순서와 표시</div>${groupsFor(ws,view).map(g=>`<div class="field-row"><span class="stage-dot" style="background:${g.color}"></span><span class="field-label">${esc(g.label)}</span><button class="icon-btn" data-action="group-up" data-stage="${esc(g.id)}" aria-label="${esc(g.label)} 앞으로">${icon('up',12)}</button><button class="icon-btn" data-action="fold-group" data-stage="${esc(g.id)}" data-view="${view.id}" aria-label="${esc(g.label)} ${g.folded?'펼치기':'접기'}">${icon(g.folded?'right':'down',12)}</button><input type="checkbox" data-action="group-visibility" data-stage="${esc(g.id)}" aria-label="${esc(g.label)} 열 표시" ${!g.hidden?'checked':''}></div>`).join('')}`+(view.groupBy==='stage'?'<button class="menu-item" data-action="add-stage">'+icon('plus',14)+'새 단계 추가</button>':'');
 if(p.kind==='group-menu'){const g=groupsFor(ws,view).find(g=>g.id===p.stage);if(!g){closePopover();return;}content=head(esc(g.label))+`<label class="config-label">이 보기의 열 이름</label><input class="config-control" data-action="group-label" data-stage="${esc(g.id)}" value="${esc(g.label)}"><button class="menu-item" data-action="fold-group" data-stage="${esc(g.id)}" data-view="${view.id}">${icon('down',15)}열 접기</button><button class="menu-item" data-action="hide-group" data-stage="${esc(g.id)}" data-view="${view.id}">${icon('eye',15)}열 숨기기</button><button class="menu-item" data-action="group-up" data-stage="${esc(g.id)}">${icon('left',15)}왼쪽으로 이동</button>`;}
 if(p.kind==='bulk-stage')content=head('선택한 기록의 단계 변경')+getField(ws,'stage',view.sourceId).options.map(s=>`<button class="menu-item" data-action="bulk-stage-apply" data-stage="${s.id}"><span class="stage-dot" style="background:${s.color}"></span>${esc(s.label)}</button>`).join('');
 $('#popover-root').innerHTML=`<div class="popover ${wide?'wide':''}" role="dialog" aria-label="${p.kind==='workspaces'?'워크스페이스 선택':p.kind==='properties'?'표시할 정보':p.kind==='filter'?'필터':p.kind==='sort'?'정렬':'보기 설정'}">${content}</div>`;
 const el=$('.popover'),width=Math.min(wide?580:345,innerWidth-24);el.style.width=width+'px';el.style.left=Math.max(12,Math.min(p.rect.left,innerWidth-width-12))+'px';el.style.top=Math.min(p.rect.bottom+7,innerHeight-180)+'px';el.style.maxHeight=Math.min(620,innerHeight-parseFloat(el.style.top)-12)+'px';
 el.querySelectorAll('label.config-label').forEach((label,index)=>{const input=label.nextElementSibling;if(input?.matches('input,select')){input.id=`popover-control-${index}`;label.htmlFor=input.id;}});
}

function openDetail(id,sourceId,linked=false){if(!recordFor(ws,id))return;if(linked&&ui.detailId)ui.detailStack.push({id:ui.detailId,source:ui.detailSource});ui.detailId=id;ui.detailSource=sourceId||currentView().sourceId||'pipeline';closePopover();renderDetail();}
function renderDetail(){
 const record=recordFor(ws,ui.detailId);if(!record){closeDetail();return;}const sourceId=ui.detailSource,view=ws.views.find(v=>v.sourceId===sourceId)||currentView(),related=entityFor(ws,record);
 const fields=getFields(ws,view).filter(f=>!['name','companyName','industry'].includes(f.id)),important=fields.filter(f=>['company','amount','stage','owner','end','category','location','area',...(ws.detailFields||[])].includes(f.id)),more=fields.filter(f=>!important.includes(f));
 const row=f=>`<div class="detail-property"><label>${icon(f.icon,14)}${esc(f.label)}</label>${editor(ws,record,f.id,sourceId)}</div>`;
 $('#detail-root').innerHTML=`<aside class="detail-panel" aria-label="기록 상세"><div class="detail-head">${ui.detailStack.length?`<button class="icon-btn" data-action="detail-back" aria-label="이전 기록">${icon('left',15)}</button>`:''}<span>${esc(sourceId==='companies'?ws.labels.entity:ws.labels.record)} 상세 · ${esc(ws.team)}</span><button class="icon-btn" data-action="close-detail" aria-label="상세 닫기">${icon('close',16)}</button></div><div class="detail-body"><div class="detail-company">${mark(ws,record)}${related?`<button data-action="related-detail" data-id="${related.id}">${esc(related.companyName)} ${icon('arrow',12)}</button>`:esc(ws.labels.entity)}</div><textarea class="detail-title" aria-label="기록 이름" data-action="detail-value" data-id="${record.id}" data-field="${sourceId==='companies'?'companyName':'name'}" data-source="${sourceId}">${esc(record.name||record.companyName)}</textarea>${important.map(row).join('')}<details class="detail-more"><summary>더 많은 정보 <span>${more.length}</span></summary>${more.map(row).join('')}</details><div class="detail-section"><h3>메모</h3><textarea class="detail-notes" aria-label="메모" data-action="detail-notes" data-id="${record.id}" placeholder="다음에 확인할 내용이나 대화를 남겨 보세요.">${esc(record.notes||'')}</textarea></div>${sourceId!=='companies'?`<div class="detail-section"><h3>선행 업무</h3>${ws.dependencies.filter(d=>d.targetId===record.id).map(d=>`<div class="dependency-chip">${icon('link',13)}<span>${esc(recordFor(ws,d.sourceId)?.name||'')}<br><small>완료 후 ${d.offset} ${d.unit==='DAY'?'일':d.unit==='HOUR'?'시간':'분'} · 시작 연결</small></span><button class="icon-btn" data-action="remove-dependency" data-id="${d.id}" aria-label="업무 연결 제거">${icon('close',12)}</button></div>`).join('')}<button class="button quiet small" data-action="add-dependency" data-id="${record.id}">${icon('plus',12)}선행 업무 연결</button></div>`:''}</div></aside>`;
}
function formRow(label,control){return `<div class="form-row"><label class="form-label">${label}</label>${control}</div>`;}
function input(name,placeholder='',extra=''){return `<input class="form-input" name="${name}" placeholder="${placeholder}" ${extra}>`;}
function layoutGrid(kind,sourceId,selected){return `<div class="layout-options layout-options-eleven">${layouts.map(l=>`<button type="button" class="layout-option ${l.id===selected?'selected':''}" data-action="${kind==='catalog'?'sample-view':'new-layout'}" data-layout="${l.id}" ${kind!=='catalog'&&!canUse(l.id,sourceId)?'disabled':''}>${icon(l.icon,21)}<strong>${l.label}</strong><p>${kind==='catalog'?esc(ws.views.find(v=>v.layout===l.id)?.name||l.description):l.description}</p>${kind==='catalog'&&l.id===selected?'<span class="layout-current">현재 보기</span>':''}</button>`).join('')}</div>`;}
function openDialog(kind,extra={}){
 closePopover();ui.dialogKind=kind;ui.dialogExtra=extra;const view=currentView();let title='',description='',body='',submit='저장';
 if(kind==='catalog'){title='같은 기록, 11가지 보기';description=`${ws.name}에 준비된 보기입니다. 업무에 맞는 화면을 선택해 보세요.`;body=layoutGrid('catalog','pipeline',view.layout);submit=null;}
 if(kind==='new-view'||kind==='change-type'){ui.newLayout=kind==='change-type'?view.layout:'table';ui.newSource=view.sourceId||'pipeline';title=kind==='change-type'?'보기 방식 변경':'새 보기 만들기';description='기록은 함께 사용하고, 표시 방식과 조건은 따로 저장해요.';submit=kind==='change-type'?'변경':'보기 만들기';body=(kind==='new-view'?formRow('보기 이름',input('name','예: 이번 주 집중할 업무','required maxlength="80"'))+formRow('어떤 기록을 볼까요?',`<select class="form-input" name="sourceId" data-action="new-source">${options(ws.sources.map(s=>({id:s.id,label:s.name})),ui.newSource)}</select>`):'')+layoutGrid('new-view',ui.newSource,ui.newLayout);}
 if(kind==='new-record'){const sourceId=extra.sourceId||view.sourceId||'pipeline',isEntity=sourceId==='companies',recordLabel=isEntity?ws.labels.entity:ws.labels.record;ui.dialogExtra.sourceId=sourceId;title=`${recordLabel} 추가`;description='필요한 정보부터 입력하고 나머지는 나중에 채워도 돼요.';submit='추가';body=formRow(`${recordLabel} 이름`,input('name',isEntity?(ws.entityPlaceholder||'예: 새 고객'):(ws.recordPlaceholder||(ws.id==='realestate'?'예: 반포 리버뷰 84㎡':ws.id==='marketing'?'예: 11월 신제품 캠페인':'예: 새봄 연간 도입')),'required'));
  if(isEntity)body+=formRow(getField(ws,'domain','companies').label,input('domain'));
  else body+=formRow(ws.labels.entity,`<select class="form-input" name="companyId">${options(ws.entities.map(e=>({id:e.id,label:e.companyName})),ws.entities[0]?.id)}</select>`)+`<div class="form-grid">${formRow(`${ws.labels.amount} · 원`,input('amount','금액 입력','type="number"'))}${sourceFor(ws,sourceId)?.type==='LIST'?formRow(getField(ws,'stage',sourceId).label,`<select class="form-input" name="stage">${options(getField(ws,'stage',sourceId).options,extra.stage||'new')}</select>`):formRow(ws.labels.category,input('category'))}</div>`+formRow(ws.labels.end,input('end','','type="date" value="'+(extra.date||'2026-10-27')+'"'))+(ws.id==='realestate'?formRow('매물 주소',input('location','예: 서울 서초구 반포동')):'')+(sourceFor(ws,sourceId)?.type==='LIST'?formRow('담당자',`<select class="form-input" name="owner">${options(ws.owners,ws.owners[0].id)}</select>`):'');
  if(!isEntity)body+=(ws.formFields||[]).filter(id=>id!=='category'||sourceFor(ws,sourceId)?.type==='LIST').map(id=>{const field=getField(ws,id,sourceId);return formRow(field.label,input(id,'',field.type==='date'?`type="date"${extra.date&&view.layout==='calendar'&&view.dateField===id?` value="${esc(extra.date)}"`:''}`:['number','currency'].includes(field.type)?'type="number" step="any"':''));}).join('');
 }
 if(kind==='new-field'){title='필요한 정보 추가';description='현재 업무에 필요한 정보를 만들어요.';submit='정보 추가';body=formRow('정보 이름',input('name','예: 다음 연락일','required maxlength="80"'))+formRow('정보 유형','<select class="form-input" name="type"><option value="text">텍스트</option><option value="number">숫자</option><option value="currency">금액</option><option value="date">날짜</option></select>')+formRow('어디에 저장할까요?',`<select class="form-input" name="scope"><option value="OBJECT">${esc(ws.labels.record)}의 기본 정보</option>${sourceFor(ws,view.sourceId)?.type==='LIST'?'<option value="LIST_ENTRY">이 업무 목록에서 사용하는 정보</option>':''}</select>`);}
 if(kind==='add-stage'){title='새 진행 단계';description='이 목록에서 사용할 단계를 추가합니다.';submit='단계 추가';body=formRow('단계 이름',input('name','예: 검토 중','required maxlength="40"'));}
 if(kind==='add-widget'){title='업무 요약에 보기 추가';description='이 워크스페이스에 있는 보기를 연결합니다.';submit='추가';body=formRow('표시할 보기',`<select class="form-input" name="viewId">${options(ws.views.filter(v=>v.layout!=='dashboard').map(v=>({id:v.id,label:`${v.name} · ${layoutFor(v.layout)?.label}`})),ws.views.find(v=>v.layout==='chart')?.id)}</select>`)+formRow('대시보드에서 사용할 제목',input('name','원래 보기 이름 사용'));}
 if(kind==='widget-title'){title='위젯 제목 변경';body=formRow('제목',input('name','','required value="'+esc(view.widgets.find(w=>w.id===extra.id)?.title)+'"'));}
 if(kind==='add-dependency'){title='선행 업무 연결';description='선행 업무가 끝난 뒤 시작할 업무의 연결과 시간 간격을 지정합니다.';submit='연결';body=formRow('선행 업무',`<select class="form-input" name="sourceId">${options(ws.records.filter(r=>r.id!==extra.id).map(r=>({id:r.id,label:r.name})),ws.records.find(r=>r.id!==extra.id)?.id)}</select>`)+`<div class="form-grid">${formRow('완료 후 시간 간격',input('offset','','type="number" step="any" value="0"'))}${formRow('단위','<select class="form-input" name="unit"><option value="DAY">일</option><option value="HOUR">시간</option><option value="MINUTE">분</option></select>')}</div>`;}
 if(kind==='quick-search'){title=`${ws.team}에서 찾기`;description='현재 워크스페이스의 기록을 검색해요.';body='<input class="form-input" id="quick-query" aria-label="워크스페이스 기록 검색" placeholder="이름이나 위치로 검색"><div id="quick-results" class="search-results"></div>';submit=null;}
 if(kind==='help'){title='업무 공간을 직접 사용해 보세요';description=`${store.workspaces.length}개 워크스페이스의 데이터와 보기는 각각 따로 저장돼요.`;body='<ol class="help-list"><li>왼쪽 위에서 워크스페이스를 전환하세요.</li><li>11가지 보기 둘러보기에서 원하는 화면을 선택하세요.</li><li>목록에서 표·칸반·캘린더처럼 보기를 바꿔보세요.</li><li>기록을 열어 수정하거나 새 기록을 추가하세요.</li><li>보기 설정에서 표시 정보와 조건을 바꾸세요.</li><li>업무 요약에 기존 보기를 모아보세요.</li></ol><div class="tip">예시 데이터를 사용하는 로컬 UX 목업입니다. 변경은 이 브라우저에 저장됩니다. 지도는 서울 지역 개략도입니다.</div>';submit=null;}
 if(kind==='delete-view'){title='이 보기를 삭제할까요?';description='기록은 유지되고 보기 설정만 삭제됩니다. 되돌리기로 복구할 수 있어요.';body=`<div class="help-card"><h3>${esc(view.name)}</h3></div>`;submit='보기 삭제';}
 const dialog=$('#dialog');dialog.classList.toggle('modal-large',['catalog','new-view','change-type'].includes(kind));dialog.innerHTML=`<form id="modal-form"><header class="modal-head"><div><h2>${title}</h2><p>${description}</p></div><button class="icon-btn" type="button" data-action="close-dialog" aria-label="닫기">${icon('close',16)}</button></header><div class="modal-body">${body}<p id="form-error" class="form-error" role="alert"></p></div><footer class="modal-foot"><button class="button" type="button" data-action="close-dialog">${submit?'취소':'닫기'}</button>${submit?`<button class="button primary" type="submit">${submit}</button>`:''}</footer></form>`;dialog.showModal();dialog.querySelectorAll('label.form-label').forEach((label,i)=>{const control=label.parentElement.querySelector('input,select');if(control){control.id=`modal-control-${i}`;label.htmlFor=control.id;}});if(kind==='quick-search'){$('#quick-query').addEventListener('input',e=>renderQuickResults(e.target.value));renderQuickResults('');}requestAnimationFrame(()=>dialog.querySelector('input')?.focus());
}
function renderQuickResults(query){const q=query.toLocaleLowerCase(),records=[...ws.records.map(r=>({...r,source:ws.sources.find(s=>s.type==='LIST'&&r.id in(ws.entries[s.id]||{}))?.id||'records',title:r.name,subtitle:entityFor(ws,r)?.companyName||r.location})),...ws.entities.map(e=>({...e,source:'companies',title:e.companyName,subtitle:e.domain}))].filter(r=>!q||`${r.title} ${r.subtitle} ${r.location||''}`.toLocaleLowerCase().includes(q)).slice(0,9);$('#quick-results').innerHTML=records.map(r=>`<button type="button" class="search-result" data-action="search-detail" data-id="${r.id}" data-source="${r.source}">${mark(ws,r)}<span>${esc(r.title)}<small>${esc(r.subtitle)}</small></span></button>`).join('')||'<p class="popover-sub">검색 결과가 없어요.</p>';}
function submitDialog(event){
 event.preventDefault();const data=Object.fromEntries(new FormData(event.target)),kind=ui.dialogKind,extra=ui.dialogExtra,view=currentView();if('name'in data&&kind!=='add-widget'&&!data.name.trim()){$('#form-error').textContent='이름을 입력해 주세요.';return;}
 if(kind==='new-view'){mutate(()=>{const added=makeView(ws,data.name.trim(),ui.newLayout,data.sourceId);normalizeView(added);ws.views.push(added);ws.activeView=added.id;},'새 보기를 만들었어요.');}
 if(kind==='change-type'){mutate(()=>{view.layout=ui.newLayout;if(ui.newLayout==='dashboard'){view.sourceId=null;view.widgets||=[];}else if(!view.sourceId)view.sourceId='pipeline';normalizeView(view);},'보기 방식을 바꿨어요.');}
 if(kind==='new-record'){let id;mutate(()=>{id=addRecord(ws,extra.sourceId,{...data,name:data.name.trim()});const record=recordFor(ws,id);if(data.location)record.location=data.location;if(extra.date&&view.layout==='calendar')setValue(ws,record,view.dateField,view.dateField in data?data[view.dateField]:extra.date,extra.sourceId);},'새 기록을 추가했어요.');}
 if(kind==='new-field'){mutate(()=>{const id=newId('field'),scope=data.scope,sourceId=view.sourceId;ws.fields.push({id,label:data.name.trim(),type:data.type,icon:data.type==='date'?'date':['number','currency'].includes(data.type)?'number':'text',source:scope==='LIST_ENTRY'?'이 목록의 정보':'기본 정보',scope,scopes:scope==='LIST_ENTRY'?[sourceId]:sourceId==='companies'?['companies']:['records','pipeline','secondary']});view.props.push({fieldId:id,role:'BODY',width:180,hidden:false});},'새 정보를 추가했어요.');}
 if(kind==='add-stage'){mutate(()=>{const option={id:newId('stage'),label:data.name.trim(),color:'#7b9ac6',tint:'#eef3fc'};const source=sourceFor(ws,view.sourceId);if(source.fieldOverrides?.stage)source.fieldOverrides.stage.options.push(option);else ws.fields.find(f=>f.id==='stage').options.push(option);view.groupOrder.push(option.id);},'새 단계를 추가했어요.');}
 if(kind==='add-widget')mutate(()=>view.widgets.push({id:newId('widget'),viewId:data.viewId,title:data.name.trim()||ws.views.find(v=>v.id===data.viewId)?.name,wide:false}),'보기를 연결했어요.');
 if(kind==='widget-title')mutate(()=>view.widgets.find(w=>w.id===extra.id).title=data.name.trim(),'제목을 변경했어요.');
 if(kind==='add-dependency'){if(ws.dependencies.some(d=>d.sourceId===data.sourceId&&d.targetId===extra.id)){$('#form-error').textContent='이미 연결된 업무예요.';return;}const edges=[...ws.dependencies,{sourceId:data.sourceId,targetId:extra.id}],visit=(id,target,seen=new Set())=>{if(id===target)return true;if(seen.has(id))return false;seen.add(id);return edges.filter(e=>e.sourceId===id).some(e=>visit(e.targetId,target,seen));};if(visit(extra.id,data.sourceId)){$('#form-error').textContent='서로를 기다리는 업무 연결을 확인해 주세요.';return;}mutate(()=>ws.dependencies.push({id:newId('dep'),sourceId:data.sourceId,targetId:extra.id,type:'FS',offset:Number(data.offset)||0,unit:data.unit}),'선행 업무를 연결했어요.');}
 if(kind==='delete-view')mutate(()=>{ws.views=ws.views.filter(v=>v.id!==view.id);ws.views.filter(v=>v.layout==='dashboard').forEach(v=>v.widgets=v.widgets.filter(w=>w.viewId!==view.id));if(!ws.views.length)ws.views.push(makeView(ws,`전체 ${ws.labels.record}`,'table','pipeline'));ws.activeView=ws.views.find(v=>v.sourceId===view.sourceId)?.id||ws.views[0].id;},'보기를 삭제했어요.');
 closeDialog();
}
function startCellEdit(button){const record=recordFor(ws,button.dataset.id),field=button.dataset.field,sourceId=button.dataset.source,td=button.closest('td');if(!record||!td)return;td.innerHTML=editor(ws,record,field,sourceId,'inline-value');const control=td.querySelector('input,select');control.classList.add('cell-editor');control.focus();control.select?.();let done=false;const commit=()=>{if(done)return;done=true;const before=field==='company'?record.companyId:value(ws,record,field,sourceId);if(String(before??'')!==control.value)mutate(()=>setValue(ws,record,field,control.value,sourceId),'값을 저장했어요.');else renderWorkspace();};control.addEventListener('blur',commit);if(control.tagName==='SELECT')control.addEventListener('change',commit);control.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();commit();}if(e.key==='Escape'){done=true;renderWorkspace();}});}
function drill(view,conditions){const destination=ws.views.find(v=>v.layout==='table'&&v.sourceId===view.sourceId)||makeView(ws,`${view.name} · 기록`,'table',view.sourceId);mutate(()=>{if(!ws.views.some(v=>v.id===destination.id))ws.views.push(destination);destination.filter={id:newId('group'),operator:'AND',rules:conditions.map(c=>({id:newId('condition'),op:'eq',matchMode:'ANY',...c}))};ws.activeView=destination.id;ui.search='';ui.selected.clear();});closePopover();}

document.addEventListener('click',event=>{
 const target=event.target.closest('[data-action]');if(!target){if(ui.popover&&!event.target.closest('.popover'))closePopover();return;}const d=target.dataset,a=d.action,view=ws.views.find(v=>v.id===d.view)||currentView();
 if(['toggle-property','show-labels','select-record','select-all','group-visibility'].includes(a))return;
 if(a==='workspace'){chooseWorkspace(d.id);return;}if(a==='choose-view'){chooseView(d.id);return;}
 if(a==='source'){chooseView(ws.views.find(v=>v.sourceId===d.id&&v.layout==='table')?.id||ws.views.find(v=>v.sourceId===d.id)?.id);return;}
 if(a==='home'){chooseView(ws.views.find(v=>v.layout==='dashboard')?.id);return;}
 if(a==='sample-view'){const demo=ws.views.find(v=>v.layout===d.layout);if(demo)chooseView(demo.id);else{closeDialog();openDialog('new-view');ui.newLayout=d.layout;document.querySelectorAll('.layout-option').forEach(el=>el.classList.toggle('selected',el.dataset.layout===d.layout));}return;}
 if(a==='mobile'){ui.mobile=!ui.mobile;$('#app').classList.toggle('sidebar-open',ui.mobile);return;}
 if(['workspaces','settings','filter','sort','group','properties','bulk-stage'].includes(a)){showPopover(a,target);return;}
 if(a==='group-menu'){showPopover(a,target,{stage:d.stage,viewId:d.view});return;}
 if(a==='field-menu'){showPopover('field',target,{fieldId:d.field,viewId:d.view});return;}
 if(['catalog','new-view','change-type','new-record','new-field','add-stage','add-widget','quick-search','help','delete-view'].includes(a)){openDialog(a,{stage:d.stage,date:d.date});return;}
 if(a==='close-popover'){closePopover();return;}if(a==='close-dialog'){closeDialog();return;}if(a==='close-detail'){closeDetail();return;}
 if(a==='detail'){openDetail(d.id,d.source);return;}if(a==='related-detail'){openDetail(d.id,'companies',true);return;}if(a==='detail-back'){const previous=ui.detailStack.pop();if(previous){ui.detailId=previous.id;ui.detailSource=previous.source;renderDetail();}return;}
 if(a==='search-detail'){closeDialog();openDetail(d.id,d.source);return;}if(a==='edit-cell'){closePopover();startCellEdit(target);return;}
 if(a==='undo'){undo();return;}
 if(a==='reset'){mutate(()=>{const index=store.workspaces.findIndex(w=>w.id===ws.id);store.workspaces[index]=createWorkspace(workspaceSeeds.find(s=>s.id===ws.id));ws=store.workspaces[index];resetUi();},'현재 워크스페이스의 예시를 초기화했어요.');return;}
 if(a==='new-layout'){ui.newLayout=d.layout;document.querySelectorAll('.layout-option').forEach(el=>el.classList.toggle('selected',el.dataset.layout===d.layout));return;}
 if(a==='duplicate-view'){mutate(()=>{const copy=structuredClone(view);copy.id=newId('view');copy.name=view.name+' 복사본';if(copy.layout==='dashboard')copy.widgets.forEach(w=>w.id=newId('widget'));ws.views.push(copy);ws.activeView=copy.id;},'현재 보기를 복제했어요.');closePopover();return;}
 if(a==='move-prop'){const from=view.props.findIndex(p=>p.fieldId===d.field),to=from+Number(d.step);if(to>=0&&to<view.props.length)mutate(()=>{const[p]=view.props.splice(from,1);view.props.splice(to,0,p);});renderPopover();return;}
 if(a==='hide-property'){mutate(()=>view.props.find(p=>p.fieldId===d.field).hidden=true,'이 보기에서 정보를 숨겼어요.');closePopover();return;}
 if(a==='sort-field'){mutate(()=>view.sorts=[{id:newId('sort'),fieldId:d.field,direction:d.direction}]);closePopover();return;}
 if(a==='add-sort'){mutate(()=>view.sorts.push({id:newId('sort'),fieldId:getFields(ws,view).find(f=>!view.sorts.some(s=>s.fieldId===f.id))?.id||getFields(ws,view)[0].id,direction:'ASC'}));renderPopover();return;}
 if(a==='remove-sort'){mutate(()=>view.sorts=view.sorts.filter(s=>s.id!==d.id));renderPopover();return;}
 if(a==='clear-sort'){mutate(()=>view.sorts=[]);renderPopover();return;}
 if(a==='sort-up'){const i=view.sorts.findIndex(s=>s.id===d.id);if(i>0)mutate(()=>[view.sorts[i-1],view.sorts[i]]=[view.sorts[i],view.sorts[i-1]]);renderPopover();return;}
 if(a==='add-filter'){const fieldId=view.sourceId==='companies'?'companyName':'amount';mutate(()=>findRule(view.filter,d.parent).rules.push({id:newId('condition'),fieldId,op:fieldId==='amount'?'gte':'contains',value:fieldId==='amount'?(ws.filterAmount??1000000):'',matchMode:'ANY'}));renderPopover();return;}
 if(a==='add-filter-group'){const fieldId=getFields(ws,view).some(f=>f.id==='stage')?'stage':view.sourceId==='companies'?'companyName':'category';mutate(()=>findRule(view.filter,d.parent).rules.push({id:newId('group'),operator:'OR',rules:[{id:newId('condition'),fieldId,op:'eq',value:getField(ws,fieldId,view.sourceId)?.options?.[1]?.id||'',matchMode:'ANY'}]}));renderPopover();return;}
 if(a==='remove-filter'){mutate(()=>removeRule(view.filter,d.id));renderPopover();return;}
 if(a==='clear-filters'){mutate(()=>{view.filter.rules=[];ui.search='';});if(ui.popover)renderPopover();return;}
 if(['fold-group','hide-group','group-up'].includes(a)){mutate(()=>{view.groupSettings[d.stage]||={};if(a==='fold-group')view.groupSettings[d.stage].folded=!view.groupSettings[d.stage].folded;if(a==='hide-group')view.groupSettings[d.stage].hidden=true;if(a==='group-up'){const i=view.groupOrder.indexOf(d.stage);if(i>0)[view.groupOrder[i-1],view.groupOrder[i]]=[view.groupOrder[i],view.groupOrder[i-1]];}});if(ui.popover?.kind==='group')renderPopover();else closePopover();return;}
 if(a==='deselect'){ui.selected.clear();renderWorkspace();return;}
 if(a==='bulk-stage-apply'){mutate(()=>ws.records.filter(r=>ui.selected.has(r.id)).forEach(r=>setValue(ws,r,'stage',d.stage,view.sourceId)),'선택한 기록의 단계를 변경했어요.');ui.selected.clear();closePopover();renderWorkspace();return;}
 if(a==='calendar-month'){const month=new Date(ui.calendarMonth+'-01T00:00:00Z');month.setUTCMonth(month.getUTCMonth()+Number(d.step));ui.calendarMonth=month.toISOString().slice(0,7);renderWorkspace();return;}
 if(a==='calendar-today'){ui.calendarMonth='2026-10';renderWorkspace();return;}if(a==='timeline-shift'){ui.timelineStart=addDays(ui.timelineStart,Number(d.days));renderWorkspace();return;}if(a==='timeline-today'){ui.timelineStart='2026-10-12';renderWorkspace();return;}
 if(a==='chart-drill'){drill(view,[{fieldId:view.chartGroup,value:d.group}]);return;}if(a==='pivot-drill'){drill(view,[{fieldId:view.pivotRow,value:d.row},{fieldId:view.pivotColumn,value:d.col}]);return;}
 if(a==='map-select'){ui.mapSelected=d.id;renderWorkspace();return;}if(a==='map-zoom'){mutate(()=>view.mapZoom=Math.max(.75,Math.min(2.5,(view.mapZoom||1)+Number(d.step))));return;}
 if(a==='widget-title'){openDialog(a,{id:d.id});return;}if(a==='widget-size'){mutate(()=>{const widget=view.widgets.find(w=>w.id===d.id);widget.wide=!widget.wide;});return;}
 if(a==='widget-move'){const i=view.widgets.findIndex(w=>w.id===d.id),to=i+Number(d.step);if(to>=0&&to<view.widgets.length)mutate(()=>{const[w]=view.widgets.splice(i,1);view.widgets.splice(to,0,w);},'보기 위치를 바꿨어요.');return;}
 if(a==='remove-widget'){mutate(()=>view.widgets=view.widgets.filter(w=>w.id!==d.id),'대시보드에서 보기를 제거했어요.');return;}
 if(a==='add-dependency'){openDialog(a,{id:d.id});return;}if(a==='remove-dependency'){mutate(()=>ws.dependencies=ws.dependencies.filter(d=>d.id!==target.dataset.id),'업무 연결을 제거했어요.');return;}
});
document.addEventListener('change',event=>{
 const el=event.target,d=el.dataset,a=d.action,view=currentView();if(!a||a==='inline-value')return;
 if(a==='new-source'){ui.newSource=el.value;document.querySelectorAll('.layout-option').forEach(button=>button.disabled=!canUse(button.dataset.layout,el.value));if(!canUse(ui.newLayout,el.value)){ui.newLayout='table';document.querySelectorAll('.layout-option').forEach(button=>button.classList.toggle('selected',button.dataset.layout==='table'));}return;}
 if(a==='select-record'){el.checked?ui.selected.add(d.id):ui.selected.delete(d.id);renderWorkspace();return;}if(a==='select-all'){currentRecords().forEach(r=>el.checked?ui.selected.add(r.id):ui.selected.delete(r.id));renderWorkspace();return;}
 if(a==='view-option'){mutate(()=>view[d.option]=el.value);return;}
 if(a==='view-name'){if(el.value.trim())mutate(()=>view.name=el.value.trim());return;}
 if(a==='toggle-property'){mutate(()=>{let p=view.props.find(p=>p.fieldId===d.field);if(!p){p={fieldId:d.field,role:'BODY',hidden:false,width:180};view.props.push(p);}p.hidden=!el.checked;});renderPopover();return;}
 if(a==='card-title'){mutate(()=>{view.props.forEach(p=>p.role='BODY');let prop=view.props.find(p=>p.fieldId===el.value);if(!prop){prop={fieldId:el.value,width:280,hidden:false};view.props.unshift(prop);}prop.role='TITLE';prop.hidden=false;});renderPopover();return;}
 if(a==='show-labels'){mutate(()=>view.showLabels=el.checked);return;}
 if(['property-label','property-width'].includes(a)){mutate(()=>{const prop=view.props.find(p=>p.fieldId===d.field);if(a==='property-label')prop.label=el.value.trim()||null;else prop.width=Math.max(60,Math.min(700,Number(el.value)||180));});return;}
 if(a.startsWith('filter-')){const rule=findRule(view.filter,d.id);if(!rule)return;mutate(()=>{if(a==='filter-operator')rule.operator=el.value;if(a==='filter-field'){rule.fieldId=el.value;rule.op='eq';rule.value=getField(ws,el.value,view.sourceId)?.options?.[0]?.id||'';}if(a==='filter-op')rule.op=el.value;if(a==='filter-value')rule.value=el.value;if(a==='filter-match')rule.matchMode=el.value;});if(a!=='filter-value')renderPopover();return;}
 if(a==='sort-field-change'||a==='sort-direction'){mutate(()=>view.sorts.find(s=>s.id===d.id)[a==='sort-field-change'?'fieldId':'direction']=el.value);return;}
 if(a==='group-by'){mutate(()=>{view.groupBy=el.value;view.groupOrder=(getField(ws,el.value,view.sourceId)?.options||[]).map(o=>o.id);view.groupSettings={};});renderPopover();return;}
 if(a==='group-label'){mutate(()=>{view.groupSettings[d.stage]||={};if(el.value.trim())view.groupSettings[d.stage].label=el.value.trim();else delete view.groupSettings[d.stage].label;});return;}
 if(a==='group-visibility'){mutate(()=>{view.groupSettings[d.stage]||={};view.groupSettings[d.stage].hidden=!el.checked;});return;}
 if(a==='detail-value'||a==='detail-notes'){const record=recordFor(ws,d.id);mutate(()=>a==='detail-notes'?record.notes=el.value:setValue(ws,record,d.field,el.value,d.source),null,false);renderHeader();renderWorkspace();renderStatus();return;}
});
document.addEventListener('submit',event=>{if(event.target.id==='modal-form')submitDialog(event);});
document.addEventListener('dragstart',event=>{
 const record=event.target.closest('[data-record-drag]'),group=event.target.closest('[data-group-drag]'),widget=event.target.closest('[data-widget-drag]'),field=event.target.closest('th[data-field-id]');
 if(record){event.dataTransfer.setData('application/x-onehand-record',record.dataset.recordDrag);event.dataTransfer.setData('application/x-onehand-view',record.dataset.view);record.classList.add('dragging');}
 else if(group){event.dataTransfer.setData('application/x-onehand-group',group.dataset.groupDrag);event.dataTransfer.setData('application/x-onehand-view',group.closest('[data-view]').dataset.view);}
 else if(widget)event.dataTransfer.setData('application/x-onehand-widget',widget.dataset.widgetDrag);
 else if(field)event.dataTransfer.setData('application/x-onehand-field',field.dataset.fieldId);
});
document.addEventListener('dragover',event=>{const target=event.target.closest('.board-column,.calendar-day,.widget,th[data-field-id]');if(target){event.preventDefault();target.classList.add('drop-target');}});
document.addEventListener('dragleave',event=>{const target=event.target.closest('.drop-target');if(target&&!target.contains(event.relatedTarget))target.classList.remove('drop-target');});
document.addEventListener('dragend',()=>document.querySelectorAll('.dragging,.drop-target').forEach(el=>el.classList.remove('dragging','drop-target')));
document.addEventListener('drop',event=>{
 const transfer=event.dataTransfer,id=transfer.getData('application/x-onehand-record'),group=transfer.getData('application/x-onehand-group'),widget=transfer.getData('application/x-onehand-widget'),field=transfer.getData('application/x-onehand-field'),column=event.target.closest('.board-column'),day=event.target.closest('.calendar-day'),card=event.target.closest('.widget'),heading=event.target.closest('th[data-field-id]');
 const view=ws.views.find(v=>v.id===transfer.getData('application/x-onehand-view'))||currentView();
 if(id&&(column||day)){event.preventDefault();const record=recordFor(ws,id);if(record)mutate(()=>setValue(ws,record,column?view.groupBy:view.dateField,column?column.dataset.stage:day.dataset.calendarDay,view.sourceId),column?'이 목록의 단계를 변경했어요.':'일정을 변경했어요.');}
 if(group&&column){event.preventDefault();const from=view.groupOrder.indexOf(group),to=view.groupOrder.indexOf(column.dataset.stage);if(from>=0&&to>=0&&from!==to)mutate(()=>{view.groupOrder.splice(from,1);view.groupOrder.splice(to,0,group);},'열 순서를 바꿨어요.');}
 if(widget&&card){event.preventDefault();const parent=currentView(),from=parent.widgets.findIndex(w=>w.id===widget),to=parent.widgets.findIndex(w=>w.id===card.dataset.widget);if(from>=0&&to>=0&&from!==to)mutate(()=>{const[w]=parent.widgets.splice(from,1);parent.widgets.splice(to,0,w);},'보기 위치를 바꿨어요.');}
 if(field&&heading){event.preventDefault();const active=currentView(),from=active.props.findIndex(p=>p.fieldId===field),to=active.props.findIndex(p=>p.fieldId===heading.dataset.fieldId);if(from>=0&&to>=0&&from!==to)mutate(()=>{const[p]=active.props.splice(from,1);active.props.splice(to,0,p);},'정보 순서를 바꿨어요.');}
 document.querySelectorAll('.drop-target').forEach(el=>el.classList.remove('drop-target'));
});
document.addEventListener('keydown',event=>{
 if(event.key==='Escape'){if($('#dialog').open)closeDialog();else if(ui.popover)closePopover();else if(ui.detailId)closeDetail();else if(ui.mobile){ui.mobile=false;$('#app').classList.remove('sidebar-open');}}
 if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();if(!$('#dialog').open)openDialog('quick-search');}
 if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='z'&&!['INPUT','TEXTAREA'].includes(event.target.tagName)){event.preventDefault();undo();}
 if(['Enter',' '].includes(event.key)&&event.target.matches('svg [data-action][role="button"]')){event.preventDefault();event.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}
});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog'))closeDialog();});
window.addEventListener('resize',()=>{closePopover();if(['timeline','gantt'].includes(currentView().layout))renderWorkspace();});
save();render();
